<?php require_once 'config/db.php'; require_once 'includes/auth.php'; if(!empty($_SESSION['user'])){header('Location:index.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');$pw=$_POST['password']??'';$pw2=$_POST['confirm_password']??'';if($pw!==$pw2)$err='Passwords do not match.';elseif(strlen($pw)<8)$err='Password must be at least 8 characters.';else{$hash=password_hash($pw,PASSWORD_DEFAULT);$role='customer';$s=$conn->prepare('INSERT INTO users(name,email,password,role,address) VALUES(?,?,?,?,?)');$s->bind_param('sssss',$name,$email,$hash,$role,$address);if($s->execute()){header('Location:login.php?msg=Registration+successful');exit;}else{$err='That email is already registered.';}}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customer Registration</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="container" style="max-width:520px;margin-top:50px"><div class="card"><h1>Customer Registration</h1><?php if($err):?><div class="error"><?=h($err)?></div><?php endif;?><form method="post"><label>Full name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Shipping address</label><textarea name="address" required></textarea><label>Password (minimum 8 characters)</label><input type="password" name="password" minlength="8" required><label>Confirm password</label><input type="password" name="confirm_password" minlength="8" required><button class="btn success">Register</button></form><p>Already registered? <a href="login.php">Login</a></p></div></div></body></html>